const assert=require('node:assert/strict'),{execFileSync}=require('node:child_process');let input='';
process.stdin.on('data',chunk=>input+=chunk);process.stdin.on('end',()=>main(JSON.parse(input)).catch(error=>{console.error(error.message);process.exitCode=1}));
async function main(config){assert.equal(config.database,'otog_audit_test_20261021');assert.equal(config.base,'http://127.0.0.1:18021');const checks=[];
 const sql=query=>execFileSync('docker',['exec','-i','otog-postgres-1','psql','-X','-U','otog','-d',config.database,'-v','ON_ERROR_STOP=1','-tA'],{input:query,encoding:'utf8',stdio:['pipe','pipe','pipe']}).trim();
 async function get(route,token){const reply=await fetch(config.base+route,{headers:token?{Authorization:'Bearer '+token}:{}});return{status:reply.status,body:await reply.json(),headers:reply.headers}}
 async function upload(token,number){const body=new FormData();body.set('language','cpp');body.set('sourceCode',new File(['int main(){return '+number+';}'],'fixture.cpp'));const reply=await fetch(config.base+'/submission/problem/770000?contestId=%22770000%22',{method:'POST',headers:{Authorization:'Bearer '+token},body});assert.equal(reply.status,200);return reply.json()}
 sql(`INSERT INTO problem(id,name,score,"timeLimit","memoryLimit",show,"case") VALUES(770000,'Page cache fixture',100,1000,131072,false,'1');INSERT INTO contest(id,name,mode,"gradingMode","scoreboardPolicy","timeStart","timeEnd") VALUES(770000,'Page fixture','unrated','classic','AFTER_CONTEST',now()-interval '1 hour',now()+interval '1 hour');INSERT INTO "contestProblem"("contestId","problemId") VALUES(770000,770000);`);
 const one=await upload(config.oneToken,11),two=await upload(config.twoToken,22);const route='/contest/770000/problem/770000/page';
 const first=await get(route,config.oneToken);assert.equal(first.status,200);assert.equal(first.body.latestSubmission.id,one.id);assert(first.body.latestSubmission.sourceCode.includes('11'));assert.equal(first.headers.get('cache-control'),'private, no-store');
 const other=await get(route,config.twoToken);assert.equal(other.body.latestSubmission.id,two.id);assert(other.body.latestSubmission.sourceCode.includes('22'));assert(!JSON.stringify(other.body).includes('return 11'));assert([401,403].includes((await get(route)).status));
 const many=await Promise.all(Array.from({length:24},()=>get(route,config.oneToken)));assert(many.every(x=>x.status===200&&x.body.latestSubmission.id===one.id));checks.push('combined page endpoint returns current time, hidden contest problem and only the requesting user’s source; guest denied and parallel reads remain private');
 sql(`UPDATE problem SET name='Edited while cached' WHERE id=770000;UPDATE contest SET name='Edited contest' WHERE id=770000;`);const edited=await get(route,config.oneToken);assert.equal(edited.body.problem.name,'Edited while cached');assert.equal(edited.body.contest.name,'Edited contest');checks.push('real PostgreSQL row versions invalidate metadata immediately after direct edits');
 sql(`UPDATE contest SET "timeStart"=now()+interval '1 hour' WHERE id=770000`);assert.equal((await get(route,config.oneToken)).status,403);const home=await get('/contest/770000/page');assert.equal(home.status,200);assert(new Date(home.body.contest.timeStart)>new Date(home.body.serverTime));
 sql(`UPDATE contest SET "timeStart"=now()-interval '1 hour' WHERE id=770000;DELETE FROM "contestProblem" WHERE "contestId"=770000;`);assert.equal((await get(route,config.oneToken)).status,404);assert.equal((await get('/contest/2147483647/page')).status,404);assert.equal((await get('/contest/invalid/page')).status,400);checks.push('warm caches preserve fresh schedule and membership checks; missing and invalid IDs keep their correct responses');
 console.log(JSON.stringify({passed:true,checks,productionWrites:0}));}
